style.css:
@-moz-document domain("downloads.khinsider.com") {
/* ============================================================
     KHInsider Dark
     The KHInsider archive (downloads.khinsider.com) is a classic
     server-rendered site with hardcoded light colors and no CSS
     custom properties, so the theme overrides per element: the
     two-column shell, the beveled sidebar module heads, the song
     /album-list tables (tan headers), the HTML5 audio player bar,
     search results, the comment threads and the legacy forms.
     Semantic reds (donate / attention) are preserved; the player
     progress + comment CTA keep a tuned, readable accent.
     ============================================================ */

  :root { color-scheme: dark !important; }

  /* ---- Base shell ---- */
  html, body {
    background-color: #14181d !important;
    background-image: none !important;
    color: #e6edf3 !important;
  }
  #container { background-color: #14181d !important; border-color: #262c33 !important; }
  #rightColumn { background-color: #14181d !important; }
  #pageContent { background-color: #14181d !important; color: #e6edf3 !important; }
  #leftColumn { background-color: #1c2128 !important; }

  /* Soften the hard light borders the layout draws between columns */
  #pageContent, #leftColumn, #rightColumn,
  #pageContent div, #homepagePopularSeries, #homepageLatestSoundtracks {
    border-color: #262c33 !important;
  }
  /* .arrow-play is a 0x0 CSS triangle: transparent top/bottom borders plus one
     solid left edge. The blanket rule above paints all four edges and fills the
     triangle into a blob — restore the transparent sides, colour only the edge. */
  #pageContent div.arrow-play {
    border-top-color: transparent !important;
    border-bottom-color: transparent !important;
    border-left-color: #8b949e !important;
  }

  /* ---- Sidebar logo + navigation ---- */
  #leftColumn h1, #leftColumn h1 a { color: #e6edf3 !important; }

  /* Beveled module heads ship a light gradient image — flatten to dark */
  #leftColumn h3 {
    background-color: #0d1117 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  #leftColumn ul li a { color: #c4cdd6 !important; }
  #leftColumn ul li a:hover { color: #9bd4ff !important; }
  /* raw red star/heart accent icons -> softened red, more legible on dark */
  #leftColumn .material-icons { color: #ff7b72 !important; }

  /* ---- Headings + body text ---- */
  h1, h2, h3, h4, h5 { color: #e6edf3 !important; }
  #pageContent p,
  #pageContent li,
  #pageContent b,
  #pageContent span,
  #pageContent div,
  #homepageText,
  #homepageText p { color: #c4cdd6 !important; }

  /* ---- Links ---- */
  #pageContent a { color: #5fb0e6 !important; }
  #pageContent a:hover { color: #9bd4ff !important; }
  /* keep attention/donate reds legible without dumping raw #f00 */
  #pageContent a[href*="donat"],
  #pageContent font[color="red"],
  #pageContent .albumMassDownload a { color: #ff7b72 !important; }

  /* ---- Tables: album list, song list, search results ---- */
  #songlist, .albumList, .requestList, #pageContent table {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* tan (#cccc99) header + total rows -> elevated dark.
     #top40 / .uploadList / #requests_table share the same light header rules. */
  #songlist th, .albumList th, .requestList th,
  #top40 th, .uploadList th, #requests_table th,
  #songlist tr.header td, #songlist .clickable-row.collapsed,
  #songlist #songlist_footer td, #songlist tr#songlist_footer th {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  #songlist td, .albumList td, .requestList td,
  #top40 td, .uploadList td, #requests_table td, #requests_table th {
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  #songlist tr td a, .albumList td a, .requestList td a,
  #top40 td a, .uploadList td a, #requests_table td a { color: #5fb0e6 !important; }
  /* Top 40 rank movement: the site marks a week's gain/loss with an inline
     `color:green` / `color:red` on the +N / -N div. Our broad `#pageContent div`
     colour is !important, so it outranks the inline pair and every gain, loss and
     no-change row rendered the same grey. Restore the two semantics with hues that
     survive a dark backdrop, and keep the arrow glyph neutral as the site does. */
  #top40 .movement div[style*="color:green"] { color: #3fb950 !important; }
  #top40 .movement div[style*="color:red"] { color: #ff7b72 !important; }
  /* zebra + hover (site paints these rows #aaa / #d2d2d2) */
  #songlist tr:hover td,
  .albumList tr:hover td,
  .requestList tr:hover td,
  #top40 tr:hover td, .uploadList tr:hover td,
  #requests_table tr:hover td, #editAlbumInfoTable tr:hover td { background-color: #1c2128 !important; }
  /* playlist row selection ships a translucent light grey */
  #songlist tr.plSel, #songlist tr.plSel td { background-color: #22303f !important; }
  /* the song "Total:" footer row */
  #songlist tr:last-child td,
  #songlist tr:last-child th { background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* table download / add-to-playlist glyphs (black originals) */
  #songlist .material-icons,
  .playlistDownloadSong .material-icons,
  .playlistAddTo .material-icons,
  .playTrack .material-icons { color: #c4cdd6 !important; }
  #songlist .material-icons:hover,
  .playlistDownloadSong .material-icons:hover,
  .playlistAddTo .material-icons:hover { color: #9bd4ff !important; }

  /* ---- Pagination (album lists, search, comment threads) ----
     The current page is a `span.pagenav` sitting on the site's own blue chip with
     `color:#fff`; the hovered page anchor is styled the same way. Our broad
     `#pageContent span` / `#pageContent a:hover` colours outrank both, so the ACTIVE
     page rendered dimmer than its unselected neighbours. Restore the white. */
  #pageContent .pagination span.pagenav { color: #ffffff !important; }
  #pageContent .pagination a:hover { color: #ffffff !important; }

  /* ---- Album art ----
     These ship `border: solid 1px` with no colour, so the border takes
     currentColor — i.e. our blue link colour — framing every thumbnail. */
  .albumImage img, .albumImage a,
  td.albumIcon img, td.albumIconLarge img,
  .albumIconDefaultSmall, .albumIconDefaultLarge { border-color: #2d333b !important; }

  /* ---- Native <audio> element (per-song download page) ----
     The song download page uses a real HTML5 <audio controls> that
     renders as a stark white default-Chrome pill — force its UA
     controls dark. (The custom .audioplayer widget is themed below.) */
  audio {
    color-scheme: dark !important;
    background-color: #1c2128 !important;
    border-radius: 8px !important;
  }

  /* ---- HTML5 audio player (custom widget) ---- */
  .audioplayer {
    background-color: #0d1117 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .audioplayer * { color: #e6edf3 !important; border-color: #2d333b !important; }
  /* every player button paints a light #d7dee5 cell on hover/focus, hiding its
     white glyph — the widget is otherwise dark */
  .audioplayerPlayPause:hover, .audioplayerPlayPause:focus,
  .audioplayerVolume:hover, .audioplayerVolume:focus,
  .audioplayerButtons:hover, .audioplayerButtons:focus,
  .audioplayerButtons2:hover, .audioplayerButtons2:focus,
  .audioplayerButtons3:hover, .audioplayerButtons3:focus {
    background-color: #1c2128 !important;
  }
  .audioplayerTimeCurrent, .audioplayerTimeDuration { color: #c4cdd6 !important; }
  .audioplayer .material-icons { color: #e6edf3 !important; }
  /* progress track + played accent */
  .audioplayerBar {
    background-color: #1c2128 !important;
    background-image: none !important;
  }
  .audioplayerBarLoaded {
    background-color: #2d333b !important;
    background-image: none !important;
  }
  .audioplayerBarPlayed {
    background-color: #5fb0e6 !important;
    background-image: none !important;
  }
  /* volume popup + level */
  .audioplayerVolumeBar, .audioplayerVolumeBarPopup {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .audioplayerVolumeBarLevel {
    background-color: #5fb0e6 !important;
    background-image: none !important;
  }

  /* ---- Comments ---- */
  #news_comments, .comment_wrap { background-color: transparent !important; }
  .comment_message {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .comment_message a { color: #5fb0e6 !important; }
  /* Commenter online/offline status ships an inline `color:red` (Offline) /
     `color:green` (Online). Our broad `#pageContent span` colour is !important and
     outranks the inline pair, so the status flattened to the same grey as the meta
     text, erasing the signal. Restore both with dark-friendly hues. */
  #pageContent .comment_meta span.status[style*="color:red"] { color: #ff7b72 !important; }
  #pageContent .comment_meta span.status[style*="color:green"] { color: #3fb950 !important; }
  /* speech-bubble pointer is a white raster triangle — tint it to the bubble color */
  .comment_graphic { filter: brightness(0.14) !important; }
  /* Commenters with no avatar get an opaque raster placeholder: a #c5c5c5 tile
     carrying a #ffffff silhouette, which glares on dark. It is image data, so it can
     only be remapped photometrically. brightness() then contrast() is an affine ramp
     that lands the tile near #2c2c2c while pushing the silhouette up to a legible
     grey. Scoped by filename so real user avatars are never touched. */
  img[src*="comment_avatar_default"] { filter: brightness(0.523) contrast(3.42) !important; }
  .quote {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .comments_headinggraphic, .comments_headinggraphic2 { color: #e6edf3 !important; }
  /* "+ Comment" CTA: original light-blue button -> tuned dark-blue, white text */
  .reply_to_comment a {
    background-color: #1f6feb !important;
    color: #ffffff !important;
  }
  #pageContent .reply_to_comment a font,
  #pageContent .reply_to_comment a span { color: #ffffff !important; }

  /* ---- Forms ---- */
  input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="text"]::placeholder, textarea::placeholder { color: #8b949e !important; }
  input[type="submit"], input[type="button"], button {
    background-color: #1c2128 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="submit"]:hover, input[type="button"]:hover, button:hover {
    background-color: #262c33 !important;
  }

  /* ---- Cookie consent banner ---- */
  .cookieinfo {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .cookieinfo a { color: #5fb0e6 !important; }
  .cookieinfo-close { color: #14181d !important; }

  /* ---- Scrollbar ---- */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #14181d; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a4250; }
}

@-moz-document url-prefix("https://downloads.khinsider.com/forums") {
/* ============================================================
     KHInsider forum (XenForo)
     The /forums/ section runs a legacy XenForo skin with no runtime
     --xf-* HSL tokens, so its hardcoded light surfaces are themed
     per element: the header/nav chrome, section-link bar, category
     blocks + node rows, form rows, the post/thread surfaces and the
     footer. The archive block above (domain scope) already darkens
     the page base, native inputs and scrollbar; this block reskins
     the XenForo chrome the archive rules don't reach. Brand blue is
     kept for links and CTAs. */

  /* ---- Base surfaces (light XenForo wrappers -> dark) ---- */
  body, .p-pageWrapper, .p-body, #top {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }
  .p-body-content a, .p-body-sidebar a, .block a, .p-breadcrumbs a { color: #5fb0e6 !important; }
  .p-body-content a:hover, .block a:hover { color: #9bd4ff !important; }

  /* ---- Header / nav chrome (XenForo blue -> deep dark) ---- */
  .p-header, .p-nav, .p-nav-inner, .p-nav-list,
  .p-navSticky, .p-navSticky.is-sticky .p-nav {
    background-color: #0d1117 !important;
    background-image: none !important;
    border-color: #20262e !important;
  }
  .p-nav-opposite a, .p-navEl-link, .p-navgroup-link,
  .p-header-content a, .p-header-logo a { color: #c4d3e8 !important; }
  /* the .is-selected WRAPPER keeps a #f5f5f5 bg of its own; the link covers it
     exactly today, so darken both rather than rely on that staying true */
  .p-navEl.is-selected { background-color: #1c232c !important; }
  .p-navEl.is-selected > .p-navEl-link,
  .p-navEl-link:hover {
    color: #ffffff !important;
    background-color: #1c232c !important;
  }
  /* While its dropdown is open, XenForo marks the parent nav tab `is-menuOpen` and
     paints it a translucent accent (rgba(71,167,235,.5)) — a state we never styled,
     so opening any nav menu lit a bright blue slab on our dark header. Match the
     selected/hover chip instead. */
  .p-navEl.is-menuOpen,
  .p-navEl-splitTrigger.is-menuOpen,
  .p-navEl.is-menuOpen > .p-navEl-link { background-color: #1c232c !important; }
  /* "Log in / Register" account pill ships a light-blue border */
  .p-navgroup.p-account .p-navgroup-link,
  .p-account a.p-navgroup-link--textual {
    color: #c4d3e8 !important;
    border-color: #2d333b !important;
  }

  /* ---- Section-links bar under the header ---- */
  .p-sectionLinks {
    background-color: #161b22 !important;
    border-color: #20262e !important;
  }
  .p-sectionLinks-list > li > a { color: #c4d3e8 !important; }
  .p-sectionLinks-list > li.is-selected > a {
    color: #ffffff !important;
    background-color: #1c232c !important;
  }

  /* ---- Breadcrumbs / page title ---- */
  .p-breadcrumbs li, .p-breadcrumbs a, .p-breadcrumbs:before { color: #aab4bf !important; }
  .p-title-value { color: #e6edf3 !important; }
  .p-description { color: #8b949e !important; }

  /* ---- Blocks / categories / node rows ---- */
  .block-container, .block-body, .block-row {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* category/section header ships a light gradient image */
  .block-header, .block-tabHeader, .block-minorTabHeader {
    background-image: linear-gradient(0deg, #161b22, #1c232c) !important;
    background-color: #1a2029 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .block-header a, .block-header .block-header-title { color: #e6edf3 !important; }
  .block-footer {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #aab4bf !important;
    border-color: #2d333b !important;
  }
  .structItem { border-color: #262c33 !important; }
  .structItem--thread:hover, .structItem.is-selected { background-color: #1c232c !important; }
  .structItem-minor, .structItem-parts,
  .structItem-cell--latest .structItem-minor { color: #aab4bf !important; }
  .node-extra, .node-meta, .node-statsMeta,
  .node-description, .node-descriptionText { color: #aab4bf !important; }
  .pairs dt { color: #8b949e !important; }
  .pairs dd { color: #c4cdd6 !important; }

  /* ---- Form rows (login / register / search) ---- */
  .formRow, .formRow > dt, .formRow > dd {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  .formRow > dt, .formRow-explain, .formRow-hint { color: #8b949e !important; }
  .inputGroup-text, .inputGroup--joined .input {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .formSubmitRow, .formSubmitRow-bar {
    background-image: none !important;
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }

  /* ---- Inputs / buttons / placeholders ---- */
  .input, .input--date, .js-editor {
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .input:focus { background-color: #1a2029 !important; border-color: #3d6a96 !important; }
  .input::placeholder, .js-editor::placeholder { color: #8b949e !important; opacity: 1 !important; }
  .button, .menuTrigger, .buttonGroup {
    background-image: none !important;
    background-color: #21262d !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .button:hover { background-color: #2a313a !important; color: #ffffff !important; }
  /* XenForo ships TWO filled action variants and paints them different hues on
     purpose: `button--primary` is blue (#47a7eb) and `button--cta` is amber
     (#f2930d), so a page carrying both still reads which action is which. We were
     painting cta the same blue as primary, collapsing that distinction. Keep the
     amber, darkened to sit on our surfaces. */
  .button.button--cta, a.button.button--cta {
    background-image: none !important;
    background-color: #b8710a !important;
    color: #ffffff !important;
    border-color: #d18410 !important;
  }
  .button.button--cta:hover, a.button.button--cta:hover { background-color: #d18410 !important; }
  /* This XenForo build marks its primary action (Log in, Register, Post) with
     `button--primary` — natively white-on-blue — not `button--cta`. The base
     `.button` rule above carries equal specificity and lands later, so every primary
     CTA was flattened to the same grey as its secondary siblings. Raise the variants
     to `.button.button--X` so they outrank the base, as XenForo's own rules do. */
  .button.button--primary, a.button.button--primary {
    background-image: none !important;
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  .button.button--primary:hover, a.button.button--primary:hover { background-color: #3b82f6 !important; }
  /* `button--plain` is a borderless, background-less text button (the mobile nav
     hamburger is one). The base rule painted it an opaque chip with a visible edge. */
  .button.button--plain, a.button.button--plain {
    background-color: transparent !important;
    border-color: transparent !important;
  }
  /* `is-bookmarked` is a STATE, not a style: the skin signals it by turning the
     bookmark button's glyph amber (#f2930d) and nothing else. Our base `.button`
     colour is !important and outranks it, so a bookmarked thread looked exactly like
     an unbookmarked one. Restore the amber. */
  .button.button--icon--bookmark.is-bookmarked,
  a.button.button--icon--bookmark.is-bookmarked { color: #e3b341 !important; }
  /* password-strength meter (register): native <meter> track is white */
  meter, .meterBar { background: #161b22 !important; border: 1px solid #2d333b !important; }
  meter::-webkit-meter-bar { background: #161b22 !important; border: none !important; }

  /* ---- Floating surfaces — keep opaque (no bleed-through) ---- */
  .menu, .menu-content, .tooltip-content, .overlay,
  .autoComplete {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Every flyout hangs a pointer triangle off its top edge: a 0x0 box whose ONLY
     opaque side is painted with the skin's accent (#47a7eb), the neighbours staying
     transparent. Against the light native menu that reads as an accent tip; on our
     dark menu it was a saturated blue spike. Repaint just the sides that can be
     opaque, to the menu's own edge colour — never the transparent neighbours, or the
     triangle fills into a rectangle. */
  .menu-arrow {
    border-top-color: #2d333b !important;
    border-bottom-color: #2d333b !important;
  }
  .menu-header, .menu-footer, .menu-footer-controls, .overlay-title {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* menu link rows keep XenForo's default #141414 text -> dark-on-dark on the
     dark flyout; force a legible light color (and text-fill) */
  .menu-row, .menu-linkRow, .menu-row > a, .menu-linkRow > a {
    color: #c4d3e8 !important;
    -webkit-text-fill-color: #c4d3e8 !important;
    border-color: #2d333b !important;
  }
  /* hover AND keyboard/split-trigger focus + selected states — XenForo paints the
     highlighted row a light #e8f4fc, so the focused first row was light-on-light */
  .menu-row:hover, .menu-linkRow:hover,
  .menu-row > a:hover, .menu-linkRow:hover > a,
  .menu-row:focus, .menu-linkRow:focus,
  .menu-row > a:focus, .menu-linkRow:focus > a,
  .menu-row.is-selected, .menu-linkRow.is-selected,
  .menu-row--selected, a.menu-linkRow.menu-row--selected {
    background-color: #232a33 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* Member card (hover a username): XenForo paints the header band #e8f4fc and lets
     its text inherit. Inside our dark tooltip the band stays light while the username
     and user title inherit our light palette, so both read as ghosts. Darken the band
     rather than re-darken the text. The class carries a per-user size suffix
     (memberProfileBanner-u123-m / -l), so target the base class. */
  .memberProfileBanner {
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }
  /* The user-group badge inside that card ("Staff member") is an identity chip the
     skin paints as a LIGHT tile with coloured text — #e8f4fc/blue for staff+primary,
     #fef4e7/brown for accent. Both survived our theme untouched and glared as light
     pills on the dark card. Keep each badge's hue as the signal, carry it on the text
     and border, and drop the tile to a dark chip. The saturated variants (red, green,
     blue, gray…) are already white-on-colour and stay as the site ships them. */
  .userBanner.userBanner--staff,
  .userBanner.userBanner--primary {
    background-color: #16263a !important;
    color: #79c0ff !important;
    border-color: #2d4a6b !important;
  }
  .userBanner.userBanner--accent {
    background-color: #2e2312 !important;
    color: #e3b341 !important;
    border-color: #5a4520 !important;
  }
  /* ---- Tooltip pointer arrows ----
     Each arrow is a 0x0 box: exactly ONE border side is opaque and draws the
     triangle, the neighbours must stay transparent or the triangle fills into a
     rectangle. The rich families (member / preview / share / bookmark) paint that
     side #d6d6d6 and stack a #ffffff ::after fill on top, so a bright spike hung off
     our dark tooltip. Repaint only the side that is natively opaque for each
     placement. The basic tooltip has no fill; its arrow is a near-black triangle
     that no longer matches our elevated bubble. */
  .tooltip--basic.tooltip--top .tooltip-arrow { border-top-color: #1c2128 !important; }
  .tooltip--basic.tooltip--bottom .tooltip-arrow { border-bottom-color: #1c2128 !important; }
  .tooltip--basic.tooltip--right .tooltip-arrow { border-right-color: #1c2128 !important; }
  .tooltip--basic.tooltip--left .tooltip-arrow { border-left-color: #1c2128 !important; }

  .tooltip--member.tooltip--top .tooltip-arrow,
  .tooltip--preview.tooltip--top .tooltip-arrow,
  .tooltip--share.tooltip--top .tooltip-arrow,
  .tooltip--bookmark.tooltip--top .tooltip-arrow { border-top-color: #2d333b !important; }
  .tooltip--member.tooltip--bottom .tooltip-arrow,
  .tooltip--preview.tooltip--bottom .tooltip-arrow,
  .tooltip--share.tooltip--bottom .tooltip-arrow,
  .tooltip--bookmark.tooltip--bottom .tooltip-arrow { border-bottom-color: #2d333b !important; }
  .tooltip--member.tooltip--right .tooltip-arrow,
  .tooltip--preview.tooltip--right .tooltip-arrow,
  .tooltip--share.tooltip--right .tooltip-arrow,
  .tooltip--bookmark.tooltip--right .tooltip-arrow { border-right-color: #2d333b !important; }
  .tooltip--member.tooltip--left .tooltip-arrow,
  .tooltip--preview.tooltip--left .tooltip-arrow,
  .tooltip--share.tooltip--left .tooltip-arrow,
  .tooltip--bookmark.tooltip--left .tooltip-arrow { border-left-color: #2d333b !important; }

  .tooltip--member.tooltip--top .tooltip-arrow::after,
  .tooltip--preview.tooltip--top .tooltip-arrow::after,
  .tooltip--share.tooltip--top .tooltip-arrow::after,
  .tooltip--bookmark.tooltip--top .tooltip-arrow::after { border-top-color: #1c2128 !important; }
  .tooltip--preview.tooltip--bottom .tooltip-arrow::after,
  .tooltip--share.tooltip--bottom .tooltip-arrow::after,
  .tooltip--bookmark.tooltip--bottom .tooltip-arrow::after { border-bottom-color: #1c2128 !important; }
  .tooltip--member.tooltip--right .tooltip-arrow::after,
  .tooltip--preview.tooltip--right .tooltip-arrow::after,
  .tooltip--share.tooltip--right .tooltip-arrow::after,
  .tooltip--bookmark.tooltip--right .tooltip-arrow::after { border-right-color: #1c2128 !important; }
  .tooltip--member.tooltip--left .tooltip-arrow::after,
  .tooltip--preview.tooltip--left .tooltip-arrow::after,
  .tooltip--share.tooltip--left .tooltip-arrow::after,
  .tooltip--bookmark.tooltip--left .tooltip-arrow::after { border-left-color: #1c2128 !important; }
  /* a member card opening downward points at its own profile banner, not the body */
  .tooltip--member.tooltip--bottom .tooltip-arrow::after { border-bottom-color: #161b22 !important; }
  /* the preview tooltip masks its clipped text with a white "more below" gradient */
  .tooltip--preview .tooltip-content-cover { background-image: none !important; }

  .offCanvasMenu-content, .offCanvasMenu-header {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* the open mobile nav marks the current section with a #f5f5f5 bar, which left the
     pale link text stranded on white */
  .offCanvasMenu-linkHolder.is-selected { background-color: #1c232c !important; }
  .offCanvasMenu-linkHolder.is-selected > a,
  .offCanvasMenu-linkHolder.is-selected > a > span {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* the "or" rule on the login form/overlay is a #d6d6d6 pseudo-element border */
  .blocks-textJoiner span::before,
  .blocks-textJoiner span::after { border-color: #2d333b !important; }
  /* ---- Notice blocks ----
     Every notice carries the base `.blockMessage` class plus a modifier. A bare
     `.blockMessage` rule therefore has the SAME specificity as `.blockMessage--error`
     and, landing later, silently overrode it — our red error styling never rendered,
     and XenForo's own success / warning / important variants were flattened to the
     same neutral grey, accent stripe included. Every modifier below is written
     `.blockMessage.blockMessage--X` so it outranks the base, mirroring XenForo. */
  .blockMessage, .blockMessage--none, .blockMessage--info {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .blockMessage.blockMessage--error {
    background-color: #3a1d1f !important;
    color: #ff9a93 !important;
    border-color: #5a2b2e !important;
    border-left-color: #f53d43 !important;
  }
  .blockMessage.blockMessage--success {
    background-color: #16261b !important;
    color: #7ee787 !important;
    border-color: #24512d !important;
    border-left-color: #3fb950 !important;
  }
  .blockMessage.blockMessage--warning,
  .blockMessage.blockMessage--important {
    background-color: #2e2312 !important;
    color: #e3b341 !important;
    border-color: #5a4520 !important;
    border-left-color: #f2930d !important;
  }
  .blockMessage.blockMessage--highlight {
    background-color: #16263a !important;
    color: #a5d6ff !important;
    border-color: #2d4a6b !important;
  }
  .blockMessage.blockMessage--alt {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* the notice's inline links inherit its hue natively; the broad body-link colour
     would otherwise repaint them brand blue on a red or amber panel */
  .blockMessage.blockMessage--error a,
  .blockMessage.blockMessage--success a,
  .blockMessage.blockMessage--warning a { color: inherit !important; }
  .blockMessage.blockMessage--important a { color: #f2930d !important; }
  /* inline field-validation tooltip bubble */
  .inputValidationError, .js-validationError {
    background-color: #3a1d1f !important;
    color: #ff9a93 !important;
    border-color: #5a2b2e !important;
  }

  /* ---- Messages / posts / quotes / code (thread view) ---- */
  .message, .message-cell, .message-inner { border-color: #2d333b !important; }
  .message-cell--user { background-color: #181d24 !important; }
  .message-name .username, .message-name a { color: #e6edf3 !important; }
  .message-userTitle, .message-attribution, .message-attribution a,
  .message-userExtras dd { color: #9aa4af !important; }
  .bbWrapper { color: #c8d1da !important; }
  blockquote.bbCodeBlock, .bbCodeBlock--quote,
  .bbCodeBlock-title, .bbCodeQuote-source {
    background-color: #181d24 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .bbCodeCode, .bbCodeBlock--code .bbCodeBlock-content, pre, code, kbd {
    background-color: #0d1117 !important;
    color: #c9d1d9 !important;
    border-color: #2d333b !important;
  }

  /* ---- Pagination ----
     XenForo pages the list with a light default palette: the page <li>
     wrappers (#e8f4fc), the Next/Last jump buttons (light gradient) and
     the per-row "page N" jump pills (#fef4e7) all ship light. Darken the
     wrappers + buttons, not just the inner <a>. */
  .pageNav-page, .pageNav-page a,
  .pageNav-jump, .pageNavSimple-el {
    background-image: none !important;
    background-color: #1c2128 !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .pageNav-page--current a, .pageNav-page--current {
    background-image: none !important;
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  .pageNav-jump, .pageNavSimple-el { color: #5fb0e6 !important; }
  /* per-row page-jump pills inside thread rows */
  .structItem-pageJump a {
    background-image: none !important;
    background-color: #21262d !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }

  /* filter/sort bar above thread lists ships a light gradient strip */
  .block-filterBar, .filterBar {
    background-image: none !important;
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }
  .filterBar a, .filterBar-menuTrigger { color: #5fb0e6 !important; }

  /* standalone tab strip (What's new / member-profile tabs) ships a white bar */
  .tabs, .tabs--standalone {
    background-color: #161b22 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .tabs-tab, .tabs-tab a { color: #c4d3e8 !important; }
  .tabs-tab.is-active, .tabs-tab.is-active a { color: #5fb0e6 !important; }
  .tabs-tab:hover { color: #9bd4ff !important; }

  /* ---- Footer ---- */
  .p-footer, .p-footer-inner, .p-footer-row {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #20262e !important;
  }
  .p-footer a { color: #aab4bf !important; }

  /* avatars / image wrappers stay transparent (no white tile). The <img> itself
     carries a white disc that opaque JPEGs hide but transparent PNGs do not. */
  .avatar, .avatarWrapper, .contentRow-figure,
  .structItem-iconContainer, .avatar img { background-color: transparent !important; }
  /* Letter avatars: XenForo paints a per-user chip via inline style
     (background-color + a matched initial). The transparent rule above erases the
     chip and the broad link colour repaints the initial, leaving a bare blue letter.
     We do NOT restore the inline pair: the generated palette is built for a light
     page and half of it IS light — #ccadeb with a #732eb8 initial sits right next to
     #1f3d7a with a #7094db one — so honouring it would scatter bright discs down
     every thread row. One coherent dark chip for all of them instead.
     `a.avatar--default` must stay at least as specific as `.p-body-content a`. */
  .avatar--default, a.avatar--default {
    background-color: #21262d !important;
    color: #c4d3e8 !important;
    -webkit-text-fill-color: #c4d3e8 !important;
  }
}
